+/** Theoretical use from sales vs actual consume movements per item between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  if (!isDate(from) || !isDate(to)) throw new AppError("invalid_date");
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const theo = new Map();
+  const act = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    act.set(itemId, Math.round(((act.get(itemId) ?? 0) + m.qty) * 1000) / 1000);
+    if (typeof m.ref === "string" && m.ref.startsWith("sale:"))
+      theo.set(itemId, Math.round(((theo.get(itemId) ?? 0) + m.qty) * 1000) / 1000);
+  }
+  const itemIds = new Set([...theo.keys(), ...act.keys()]);
+  return [...itemIds]
+    .sort((a, b) => a - b)
+    .map((itemId) => {
+      const theoretical = theo.get(itemId) ?? 0;
+      const actual = act.get(itemId) ?? 0;
+      return { itemId, theoretical, actual, diff: Math.round((actual - theoretical) * 1000) / 1000 };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
