+++ b/src/io/sales-import.js
@@ -0,0 +1,67 @@
+// Importing sales from the till CSV (ticket,soldAt,dishId,qty).
+// Each dish sold uses one portion of its recipe per qty. Already-imported
+// tickets are skipped; one bad row or stock shortage imports nothing.
+import { isInstant } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Imports till sales from CSV; returns { tickets, dishes } counts or throws naming the row. */
+export function importSales(store, text) {
+  const rows = parseCsvObjects(text);
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    for (const k of HEADER) if (!(k in r)) throw new AppError("bad_request", { reason: `${where}: missing column ${k}` });
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const dishId = Number(r.dishId);
+    const dish = (store.data.dishes ?? []).find((d) => d.id === dishId);
+    if (!r.dishId || !Number.isInteger(dishId) || !dish) throw new AppError("bad_request", { reason: `${where}: unknown dish` });
+    const recipe = store.data.recipes.find((rec) => rec.id === dish.recipeId);
+    if (!recipe) throw new AppError("bad_request", { reason: `${where}: unknown recipe` });
+    const qty = Number(r.qty);
+    if (!r.qty || !Number.isInteger(qty) || qty < 1) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return { where, ticket: r.ticket, soldAt: r.soldAt, dishId, qty, recipe };
+  });
+
+  const alreadyImported = new Set(
+    store.data.movements
+      .filter((m) => typeof m.ref === "string" && m.ref.startsWith("sale:"))
+      .map((m) => m.ref.slice(5)),
+  );
+  const seenInFile = new Set();
+  const snapBatches = structuredClone(store.data.batches);
+  const snapMovements = structuredClone(store.data.movements);
+  const snapSeq = structuredClone(store.data.seq);
+  const importedTickets = new Set();
+  let dishes = 0;
+
+  try {
+    for (const c of clean) {
+      if (alreadyImported.has(c.ticket) || seenInFile.has(`${c.ticket}:${c.dishId}`)) continue;
+      seenInFile.add(`${c.ticket}:${c.dishId}`);
+      for (const n of scaled(c.recipe, c.qty)) {
+        if (n.qty <= 0) continue;
+        try {
+          consume(store, n.itemId, n.qty, { at: c.soldAt, ref: `sale:${c.ticket}` });
+        } catch (e) {
+          if (e instanceof AppError && e.code === "not_enough_stock")
+            throw new AppError("not_enough_stock", { ...e.params, item: `${e.params.item} (${c.where})` });
+          throw e;
+        }
+      }
+      importedTickets.add(c.ticket);
+      dishes += c.qty;
+    }
+  } catch (e) {
+    store.data.batches = snapBatches;
+    store.data.movements = snapMovements;
+    store.data.seq = snapSeq;
+    throw e;
+  }
+
+  return { tickets: importedTickets.size, dishes };
+}
